void handle_syscall_exit(void *data, struct pt_regs *regs, long ret) {
    struct ftrace_event_file *file;
    struct ring_buffer *buffer;
    struct ring_buffer_event *event;
    unsigned int trace_ctx;
    struct ftrace_raw_sys_exit *entry;

    int syscallno = (int)PT_REGS_SYSCALL_NR(regs);
    if (syscallno < 0 || syscallno >= __NR_syscall_max)
        return;

    file = syscalls_exit_event[syscallno];
    if (!file || !file->tracing_on)
        return;

    buffer = file->ring_buffer;
    if (!buffer)
        return;

    trace_ctx = tracing_gen_ctx();
    event = ring_buffer_reserve(buffer, trace_ctx, sizeof(*entry));
    if (!event)
        return;

    entry = ring_buffer_get_entry(event);
    entry->id = syscallno;
    entry->ret = ret;

    ring_buffer_commit(event);
}

void handle_syscall_exit(void *data, struct pt_regs *regs, long ret)
{
    struct ftrace_event *event;
    struct ring_buffer *buffer = data;
    unsigned int syscall_nr = (unsigned int) regs->orig_ax;
    struct ftrace_file *file;

    if (syscall_nr >= __NR_syscall_max)
        return;

    file = syscalls[syscall_nr];
    if (!file || !file->tracing_enabled)
        return;

    event = ring_buffer_reserve(buffer, sizeof(struct ftrace_event));
    if (!event)
        return;

    event->syscall_number = syscall_nr;
    event->return_value = ret;
    ring_buffer_commit(buffer, event);
}

void syscall_exit_trace(void *data, struct pt_regs *regs, long ret) {
    struct ftrace_event_file *file;
    int syscall_nr;
    struct trace_entry *entry;
    struct ring_buffer *buffer;

    syscall_nr = syscall_get_nr(regs);
    if (syscall_nr < 0)
        return;

    file = find_event_file(data, syscalls_exit_event);
    if (!file || !file->enabled)
        return;

    buffer = file->ring_buffer;
    if (!buffer)
        return;

    entry = ring_buffer_reserve(buffer, sizeof(*entry));
    if (!entry)
        return;

    entry->type = TRACE_SYSCALL_EXIT;
    entry->pid = current->pid;
    entry->tid = current->tgid;
    entry->syscall = syscall_nr;
    entry->ret = ret;

    ring_buffer_commit(buffer);
}

void handle_syscall_exit(void *data, struct pt_regs *regs, long ret) {
    int syscall_nr = (int) regs->ax;
    struct ftrace_event_file *file = trace_get_event_file(syscall_nr);

    if (!file || !file->enabled)
        return;

    struct ring_buffer *buffer = file->ring_buffer;
    struct ring_buffer_event *event;
    struct trace_entry *entry;

    if (!buffer)
        return;

    event = ring_buffer_lock_reserve(buffer, sizeof(*entry));
    if (!event)
        return;

    entry = ring_buffer_event_data(event);
    entry->type = TRACE_SYSCALL_EXIT;
    entry->syscall_nr = syscall_nr;
    entry->ret = ret;

    ring_buffer_unlock_commit(buffer, event);
}

void handle_syscall_exit(void *data, struct pt_regs *regs, long ret) {
    struct trace_array *tr = data;
    int syscall_nr = (int) regs->ax;

    if (syscall_nr < 0 || syscall_nr >= __NR_syscall_max)
        return;

    struct ftrace_event_file *file = tr->event_file[syscall_nr];
    if (!file || !file->enabled)
        return;

    struct ring_buffer *buffer = tr->buffer;
    struct ring_buffer_event *event;
    struct syscall_exit_event *entry;

    event = ring_buffer_reserve(buffer, file->event->size, file->cpu);
    if (!event)
        return;

    entry = ring_buffer_event_data(event);
    entry->syscall_nr = syscall_nr;
    entry->ret = ret;
    ring_buffer_commit(event);
}
